        for i in range(size):
            grid[x][y + i] = '.'
            grid[x][y - i] = '.'
            grid[x + i][y] = '.'
            grid[x - i][y] = '.'
        grid[x][y] = '*'

    stars = []
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if grid[i - 1][j - 1] == '*':
                max_size = min(i - 1, j - 1, n - i, m - j)
                found_star = False
                for size in range(max_size + 1, 0, -1):
                    if can_form_star(i - 1, j - 1, size):
                        place_star(i - 1, j - 1, size)
                        stars.append((i, j, size))
                        found_star = True
                        break
                if not found_star:
                    return -1

    return stars

