def can_form_star(grid, n, m, x, y):
    """Check if a star can be centered at (x, y) without going out of bounds or overlapping non-asterisks."""
    # Check positions around the center
    positions_to_check = [
        (x, y),          # Center
        (x-1, y), (x+1, y), (x, y-1), (x, y+1),  # Rays
        (x-1, y-1), (x-1, y+1), (x+1, y-1), (x+1, y+1)  # Corners
    ]
    for i, j in positions_to_check:
        if not (0 <= i < n and 0 <= j < m):
            return False
        if (i, j) != (x, y) and grid[i][j] != '*':
            return False
    return True

